_MAC_RE = re.compile(r"^[0-9a-fA-F]{12}$|^([0-9a-fA-F]{2}[:-]){5}[0-9a-fA-F]{2}$")  # Accept compact and colon/dash MACs


def _normalize_mac(raw_mac: str) -> Optional[str]:  # Convert MAC to compact lowercase form Mist expects
    """Validate MAC and return compact 12-hex-char lowercase form, or None if invalid."""
    if not raw_mac:  # Reject empty input early
        return None
    cleaned = raw_mac.strip().lower().replace(":", "").replace("-", "")  # Strip separators
    if len(cleaned) != 12 or not all(c in "0123456789abcdef" for c in cleaned):  # Validate hex length
        return None
    return cleaned  # Return Mist-compatible MAC form


def _resolve_site_name(site_id: str) -> str:  # Look up site name for filename/display
    """Best-effort site name lookup; falls back to site_id on any failure."""
    try:
        logging.info("UPSTREAM_NEW: Resolving site name for site_id=%s", site_id)  # Log before API call
        sites_resp = mistapi.api.v1.orgs.sites.listOrgSites(
            apisession, get_cached_or_prompted_org_id()
        )  # Fetch all sites
        sites = mistapi.get_all(response=sites_resp, mist_session=apisession)  # Materialize paginated response
        name = next((s["name"] for s in sites if s.get("id") == site_id), site_id)  # Lookup by id
        logging.debug("UPSTREAM_NEW: Resolved site %s -> %s", site_id, name)  # Log resolved name
        return name
    except Exception as lookup_error:  # Any failure -> degrade to using site_id as display name
        logging.warning("UPSTREAM_NEW: Site name lookup failed for %s: %s", site_id, lookup_error)
        return site_id


def export_site_channel_scores():  # Menu 195: RF channel score export per band
    """Export RF channel scores for a site across 2.4/5/6 GHz bands.

    Calls mistapi.api.v1.sites.rrm.getSiteChannelScores once per band, flattens,
    merges, and exports via DataExporter. Safe read-only operation.
    """
    logging.info("UPSTREAM_NEW: Starting Menu 195 - Export Site RF Channel Scores")  # Action start log
    site_id = prompt_site_selection()  # Prompt user for site selection
    if not site_id:  # Bail when no site selected
        logging.error("UPSTREAM_NEW: Menu 195 aborted - no site selected")
        return
    site_name = _resolve_site_name(site_id)  # Get human-readable site name for filename
    combined: list = []  # Aggregate per-band results into single export
    for band in ("24", "5", "6"):  # Iterate all three Wi-Fi bands supported by API
        logging.info("UPSTREAM_NEW: Fetching channel scores site=%s band=%s", site_id, band)  # Per-band log
        try:
            response = mistapi.api.v1.sites.rrm.getSiteChannelScores(apisession, site_id, band)  # API call
            raw = mistapi.get_all(response=response, mist_session=apisession) or []  # Resolve to list
            logging.debug("UPSTREAM_NEW: Band %s returned %d records", band, len(raw))  # Result count log
            for record in raw:  # Tag each record with band for differentiation in flat output
                if isinstance(record, dict):  # Only mutate dict records
                    record.setdefault("band", band)  # Set band only if missing from API payload
            combined.extend(raw)  # Append to combined export buffer
        except Exception as fetch_error:  # Log per-band failure but continue with remaining bands
            logging.error("UPSTREAM_NEW: Channel score fetch failed band=%s: %s", band, fetch_error)
    if not combined:  # Nothing to export
        print("! No channel score data returned for any band.")
        logging.warning("UPSTREAM_NEW: Menu 195 produced no records for site=%s", site_id)
        return
    flat = flatten_nested_fields_in_list(combined)  # Flatten nested API response for CSV
    flat = escape_multiline_strings_for_csv(flat)  # CSV-safe multiline values
    safe_site = site_name.replace(" ", "_").replace("-", "_")  # Filesystem-safe site fragment
    filename = f"SiteChannelScores_{safe_site}.csv"  # Output filename
    logging.info("UPSTREAM_NEW: Writing %d channel score rows to %s", len(flat), filename)  # Pre-write log
    DataExporter.save_data_to_output(flat, filename, api_function_name="getSiteChannelScores")  # Persist
    print(f"! {len(flat)} channel score records exported to data/{filename}")  # User-facing summary
    logging.info("UPSTREAM_NEW: Menu 195 complete - %d rows", len(flat))  # Completion log


def search_site_iot_endpoints():  # Menu 196: IoT endpoint search (BLE/Zigbee)
    """Search IoT endpoints discovered at a site (BLE / Zigbee devices)."""
    logging.info("UPSTREAM_NEW: Starting Menu 196 - Search Site IoT Endpoints")  # Action start log
    site_id = prompt_site_selection()  # Prompt for site
    if not site_id:  # Bail when no site
        logging.error("UPSTREAM_NEW: Menu 196 aborted - no site selected")
        return
    site_name = _resolve_site_name(site_id)  # Get name for filename
    try:
        logging.info("UPSTREAM_NEW: Calling searchSiteIotEndpoints site=%s", site_id)  # Pre-call log
        response = mistapi.api.v1.sites.iotendpoints.searchSiteIotEndpoints(apisession, site_id, limit=1000)
        raw = mistapi.get_all(response=response, mist_session=apisession) or []  # Materialize
        logging.debug("UPSTREAM_NEW: searchSiteIotEndpoints returned %d records", len(raw))  # Result log
    except Exception as fetch_error:  # API-level failure
        logging.error("UPSTREAM_NEW: searchSiteIotEndpoints failed: %s", fetch_error)
        print(f"[ERROR] IoT endpoint search failed: {fetch_error}")
        return
    if not raw:  # No data path
        print("! No IoT endpoints found at this site.")
        return
    flat = escape_multiline_strings_for_csv(flatten_nested_fields_in_list(raw))  # CSV-safe rows
    safe_site = site_name.replace(" ", "_").replace("-", "_")  # Safe site fragment
    filename = f"SiteIotEndpoints_{safe_site}.csv"  # Output filename
    logging.info("UPSTREAM_NEW: Writing %d IoT endpoint rows to %s", len(flat), filename)  # Pre-write log
    DataExporter.save_data_to_output(flat, filename, api_function_name="searchSiteIotEndpoints")  # Persist
    print(f"! {len(flat)} IoT endpoint records exported to data/{filename}")  # User summary
    logging.info("UPSTREAM_NEW: Menu 196 complete - %d rows", len(flat))  # Completion log


def _prompt_mac_list(prompt_label: str) -> list:  # Reusable MAC list prompt with validation
    """Prompt user for comma-separated MACs; return list of normalized MACs."""
    raw = safe_input(f"{prompt_label} (comma-separated): ", context="nac_coa_macs")  # Get input
    if not raw:  # Empty input
        return []
    macs: list = []  # Accumulator for valid MACs
    for piece in raw.split(","):  # Split by comma
        normalized = _normalize_mac(piece)  # Validate each entry
        if normalized:  # Keep only valid
            macs.append(normalized)
        else:  # Inform user of skipped invalid entry
            print(f"! Skipping invalid MAC: '{piece.strip()}'")
            logging.warning("UPSTREAM_NEW: Skipping invalid MAC '%s'", piece.strip())
    return macs


def send_org_nac_client_coa():  # Menu 202: Org-scope NAC CoA
    """Send Change-of-Authorization to one or more NAC clients at org scope."""
    logging.info("UPSTREAM_NEW: Starting Menu 202 - Send Org NAC Client CoA")  # Action start log
    org_id = get_cached_or_prompted_org_id()  # Resolve org context
    macs = _prompt_mac_list("Enter client MAC(s) to send CoA to")  # Collect validated MACs
    if not macs:  # No valid MACs entered
        print("! No valid MACs provided. Aborting.")
        return
    for mac in macs:  # One CoA call per MAC
        logging.info("UPSTREAM_NEW: Sending CoA org=%s mac=%s", org_id, mac)  # Per-MAC pre-call log
        try:
            response = mistapi.api.v1.orgs.nac_clients.sendOrgNacClientCoA(apisession, org_id, mac)  # API
            status = getattr(response, "status_code", "n/a")  # Inspect HTTP status
            logging.debug("UPSTREAM_NEW: CoA response status=%s for mac=%s", status, mac)  # Result log
            print(f"  CoA sent to {mac}: HTTP {status}")  # User-facing per-MAC result
        except Exception as coa_error:  # API failure for this MAC - continue with next
            logging.error("UPSTREAM_NEW: CoA failed for mac=%s: %s", mac, coa_error)
            print(f"  CoA FAILED for {mac}: {coa_error}")
    logging.info("UPSTREAM_NEW: Menu 202 complete - processed %d MAC(s)", len(macs))  # Completion log


def send_site_nac_client_coa():  # Menu 203: Site-scope NAC CoA
    """Send Change-of-Authorization to NAC clients at site scope."""
    logging.info("UPSTREAM_NEW: Starting Menu 203 - Send Site NAC Client CoA")  # Action start log
