def _mxedge_sub_menu(scope_label: str, list_func, info_func, upgrade_func, status_func, cancel_func, scope_id):
    """Shared sub-menu for MxEdge upgrade management (org or site scope)."""
    while True:  # Loop until user exits sub-menu
        print(f"\n--- MxEdge Upgrade Management ({scope_label}) ---")
        print("  1. List upgrades")
        print("  2. Get upgrade info (available versions)")
        print("  3. Start upgrade (DESTRUCTIVE)")
        print("  4. Check upgrade status")
        print("  5. Cancel upgrade")
        print("  0. Back")
        choice = safe_input("Select: ", context=f"mxedge_{scope_label}_submenu")  # Sub-menu prompt
        if choice in (None, "", "0"):  # Exit conditions
            return
        try:
            if choice == "1":  # List
                logging.info("UPSTREAM_NEW: MxEdge %s list upgrades scope_id=%s", scope_label, scope_id)
                resp = list_func(apisession, scope_id)  # API
                print(f"  HTTP {getattr(resp, 'status_code', 'n/a')} - data: {getattr(resp, 'data', None)}")
            elif choice == "2":  # Info / available versions
                logging.info("UPSTREAM_NEW: MxEdge %s info scope_id=%s", scope_label, scope_id)
                resp = info_func(apisession, scope_id)  # API
                print(f"  HTTP {getattr(resp, 'status_code', 'n/a')} - data: {getattr(resp, 'data', None)}")
            elif choice == "3":  # Destructive upgrade trigger
                if not _confirm_destructive("UPGRADE", f"mxedge_{scope_label}_upgrade"):  # Typed gate
                    continue
                logging.info("UPSTREAM_NEW: MxEdge %s START upgrade scope_id=%s", scope_label, scope_id)
                resp = upgrade_func(apisession, scope_id)  # API
                print(f"  HTTP {getattr(resp, 'status_code', 'n/a')} - data: {getattr(resp, 'data', None)}")
            elif choice == "4":  # Status
                upgrade_id = safe_input("Enter upgrade id: ", context=f"mxedge_{scope_label}_status_id")
                if not upgrade_id:  # Require id
                    continue
                logging.info("UPSTREAM_NEW: MxEdge %s status upgrade_id=%s", scope_label, upgrade_id)
                resp = status_func(apisession, scope_id, upgrade_id)  # API
                print(f"  HTTP {getattr(resp, 'status_code', 'n/a')} - data: {getattr(resp, 'data', None)}")
            elif choice == "5":  # Cancel
                upgrade_id = safe_input("Enter upgrade id to cancel: ", context=f"mxedge_{scope_label}_cancel_id")
                if not upgrade_id:  # Require id
                    continue
                logging.info("UPSTREAM_NEW: MxEdge %s cancel upgrade_id=%s", scope_label, upgrade_id)
                resp = cancel_func(apisession, scope_id, upgrade_id)  # API
                print(f"  HTTP {getattr(resp, 'status_code', 'n/a')} - data: {getattr(resp, 'data', None)}")
            else:  # Unknown choice
                print("! Invalid selection")
        except Exception as menu_error:  # Per-action failure - stay in sub-menu
            logging.error("UPSTREAM_NEW: MxEdge %s sub-menu action failed: %s", scope_label, menu_error)
            print(f"[ERROR] Action failed: {menu_error}")


