def _resolve_async_claim_id(record: dict) -> str:  # Normalize varying API id field names into claim_id
    """Return normalized async-claim identifier from API record when present."""
    for candidate_key in ("claim_id", "id", "job_id", "uuid"):  # Common identifier field names
        candidate_value = record.get(candidate_key)  # Fetch candidate field value from API record
        if candidate_value:  # First truthy identifier wins
            return str(candidate_value)  # Normalize to string for CSV/SQLite consistency
    return "unknown"  # Fallback keeps composite primary key generation deterministic


def _normalize_async_claim_records(
    raw_records, org_id: str
) -> list:  # Add stable bookkeeping keys for export/persistence
    """Normalize list/dict async-claim responses into export-safe row dictionaries."""
    timestamp = datetime.now(timezone.utc).isoformat()  # Snapshot time used for composite primary keys
    source_rows = raw_records if isinstance(raw_records, list) else [raw_records]  # Always iterate a list of rows
    normalized_rows: list = []  # Accumulate normalized record dictionaries for exporter
    for raw_row in source_rows:  # Walk each API record individually
        if not isinstance(raw_row, dict):  # Wrap non-dict payloads under a stable key for flattening
            raw_row = {"value": raw_row}  # Preserve opaque payloads without dropping information
        row = dict(raw_row)  # Copy record so we never mutate API response objects in place
        row.setdefault("org_id", org_id)  # Ensure org scope is always present for composite keys
        row.setdefault("claim_id", _resolve_async_claim_id(row))  # Normalize identifier field for all endpoints
        row.setdefault("timestamp", timestamp)  # Add observation timestamp when API omits one
        normalized_rows.append(row)  # Queue normalized row for flattening/export
    return normalized_rows  # Return normalized record list to caller


def _prompt_async_claim_detail_flag(context: str) -> bool:  # Reusable yes/no prompt for detail=true API calls
    """Prompt operator whether to include per-device detail in async-claim API responses."""
    detail_input = safe_input("Include per-device detail? (y/N): ", default_value="n", context=context)  # Prompt safely
    return str(detail_input).strip().lower() in {"y", "yes", "true", "1"}  # Normalize truthy selections


def _prompt_async_claim_body() -> Optional[Union[dict, list]]:  # Collect validated JSON body for create operation
    """Prompt operator for an async-claim JSON body and return parsed dict/list or None on failure."""
    print("Enter async claim request body as JSON (single line).")  # Guide operator toward schema-safe input path
    raw_body = safe_input("JSON body: ", context="org_async_claim_body", allow_empty=False)  # Collect body text safely
    if raw_body is None or not str(raw_body).strip():  # Reject missing/blank payloads before JSON parsing
        print("! JSON body is required. Aborting.")  # User-facing validation feedback
        logging.warning("ASYNC_CLAIMS: Create aborted - empty JSON body")  # Observability for validation failure
        return None  # No API call should occur on invalid input
    try:  # Parse JSON payload using stdlib loader for deterministic schema handling
        parsed_body = json.loads(str(raw_body).strip())  # Convert operator text into Python object
    except json.JSONDecodeError as decode_error:  # Invalid JSON should fail fast before API dispatch
        print(f"! Invalid JSON body: {decode_error}")  # Explain parse failure to operator
        logging.error("ASYNC_CLAIMS: Invalid JSON body for createOrgAsyncClaim: %s", decode_error)  # Log parse error
        return None  # Caller cancels operation without hitting the API
    if not isinstance(parsed_body, (dict, list)):  # Endpoint accepts object/list payloads only
        print("! JSON body must decode to an object or list. Aborting.")  # User-facing schema guardrail
        logging.error(
            "ASYNC_CLAIMS: Parsed JSON body has invalid type %s", type(parsed_body).__name__
        )  # Log type issue
        return None  # Caller cancels operation without hitting the API
    return parsed_body  # Valid payload ready for create API call


def list_org_async_claims():  # Menu 208: safe export of org async-claim records
    """List organization async claims and export the normalized response."""
    logging.info("ASYNC_CLAIMS: Starting Menu 208 - List Org Async Claims")  # Action start log for operators
    org_id = get_cached_or_prompted_org_id()  # Resolve org context using standard MistHelper flow
    detail = _prompt_async_claim_detail_flag("org_async_claims_detail")  # Ask whether detailed records are desired
    logging.info("ASYNC_CLAIMS: Calling listOrgAsyncClaims org=%s detail=%s", org_id, detail)  # Pre-call observability
    try:  # API call is wrapped so user gets concise failure message instead of traceback noise
        response = mistapi.api.v1.orgs.claims.listOrgAsyncClaims(
            apisession, org_id, detail=detail
        )  # Fetch async claims
        raw_rows = getattr(response, "data", []) or []  # Normalize None payloads to empty list for success path
        logging.debug(
            "ASYNC_CLAIMS: listOrgAsyncClaims returned type=%s count=%s",
            type(raw_rows).__name__,
            len(raw_rows) if isinstance(raw_rows, list) else 1,
        )  # Result-shape summary
    except Exception as claim_error:  # Surface API failure cleanly and stop this safe operation
        logging.error(
            "ASYNC_CLAIMS: listOrgAsyncClaims failed for org=%s: %s", org_id, claim_error
        )  # Log failure context
        print(f"[ERROR] Async claim export failed: {claim_error}")  # Concise operator-visible failure message
        return  # Safe early exit on failure
    if not raw_rows:  # Empty result is a valid success state per contract
        print(
            "! No async claims found for this organization."
        )  # Tell operator the request succeeded but returned nothing
        logging.info("ASYNC_CLAIMS: No async claims returned for org=%s", org_id)  # Log empty-success case
        return  # No export file is generated when there are no rows
    normalized_rows = _normalize_async_claim_records(raw_rows, org_id)  # Add org_id/claim_id/timestamp scaffolding
    flattened_rows = flatten_nested_fields_in_list(
        normalized_rows
    )  # Flatten nested SDK payloads for exporter stability
    flattened_rows = escape_multiline_strings_for_csv(flattened_rows)  # Keep CSV/SQLite writes one-row-safe
    filename = "OrgAsyncClaims.csv"  # Stable filename for operator discovery and automation
    logging.info("ASYNC_CLAIMS: Writing %d async claim rows to %s", len(flattened_rows), filename)  # Pre-export log
    DataExporter.save_data_to_output(flattened_rows, filename, api_function_name="listOrgAsyncClaims")  # Persist data
    print(f"! {len(flattened_rows)} async claim records exported to data/{filename}")  # User-facing success summary
    logging.info("ASYNC_CLAIMS: Menu 208 complete - exported %d rows", len(flattened_rows))  # Completion log


def create_org_async_claim():  # Menu 209: destructive async-claim submission
    """Create an organization async claim request from operator-supplied JSON."""
    logging.info("ASYNC_CLAIMS: Starting Menu 209 - Create Org Async Claim (DESTRUCTIVE)")  # Action start log
    org_id = get_cached_or_prompted_org_id()  # Resolve org context before prompting for payload
    request_body = _prompt_async_claim_body()  # Collect and validate JSON body before confirmation
    if request_body is None:  # Invalid or missing body should abort before any destructive confirmation
        return  # Early exit preserves no-call guarantee for bad input
    if not _confirm_destructive("CREATE", "org_async_claim_create"):  # Exact typed confirmation gate required by spec
        return  # Cancel with no API dispatch if confirmation mismatches
    logging.info(
        "ASYNC_CLAIMS: Calling createOrgAsyncClaim org=%s", org_id
    )  # Pre-call observability without logging body
    try:  # Submit claim request only after payload validation + confirmation success
        response = mistapi.api.v1.orgs.claims.createOrgAsyncClaim(
            apisession, org_id, request_body
        )  # API submission call
        raw_payload = getattr(response, "data", {}) or {}  # Normalize None payloads so export logic stays consistent
        logging.debug(
            "ASYNC_CLAIMS: createOrgAsyncClaim returned status=%s payload_type=%s",
            getattr(response, "status_code", "n/a"),
            type(raw_payload).__name__,
        )  # Response summary for debugging
    except Exception as claim_error:  # API failure after confirmation should be logged and surfaced clearly
        logging.error("ASYNC_CLAIMS: createOrgAsyncClaim failed for org=%s: %s", org_id, claim_error)  # Log failure
        print(f"[ERROR] Async claim creation failed: {claim_error}")  # Operator-visible failure output
        return  # Stop after failed submission
    normalized_rows = _normalize_async_claim_records(
        raw_payload, org_id
    )  # Add claim_id/timestamp scaffolding to response
    flattened_rows = flatten_nested_fields_in_list(normalized_rows)  # Flatten response payload for export compatibility
    flattened_rows = escape_multiline_strings_for_csv(flattened_rows)  # Normalize multiline fields for CSV writer
    filename = "OrgAsyncClaimCreate.csv"  # Stable filename for claim submission audit trail
    logging.info("ASYNC_CLAIMS: Writing create response rows=%d to %s", len(flattened_rows), filename)  # Pre-write log
    DataExporter.save_data_to_output(
        flattened_rows, filename, api_function_name="createOrgAsyncClaim"
    )  # Persist audit row(s)
    claim_id = (
        normalized_rows[0].get("claim_id", "unknown") if normalized_rows else "unknown"
    )  # Extract normalized claim id for operator feedback
    print(
        f"! Async claim submitted successfully. claim_id={claim_id} (audit exported to data/{filename})"
    )  # Success summary
    logging.info("ASYNC_CLAIMS: Menu 209 complete - claim_id=%s", claim_id)  # Completion log with identifier


