SITE_MARVIS_ALLOWED_FEEDBACK_TYPES = {
    "accepted",
    "accurate",
    "helpful",
    "inaccurate",
    "not_helpful",
    "rejected",
}  # Allowlist for feedback payload type validation


def _validate_site_marvis_time_window(start_time: str, end_time: str) -> bool:  # Validate explicit time bounds
    """Return True when provided window bounds are syntactically valid and ordered."""
    start_value = str(start_time or "").strip()
    end_value = str(end_time or "").strip()
    if not start_value or not end_value:
        return True
    if start_value.isdigit() and end_value.isdigit() and int(start_value) > int(end_value):
        print("! Invalid time window: start must be less than or equal to end.")
        return False
    return True


def _validate_site_marvis_action_id(action_id: str) -> bool:  # Validate action identifier format
    """Return True when action identifier is non-empty and matches safe character set."""
    value = str(action_id or "").strip()
    if not value:
        print("! Action ID is required.")
        return False
    if not re.fullmatch(r"[A-Za-z0-9._:-]{6,}", value):
        print("! Invalid Action ID format. Use an API-provided action identifier.")
        return False
    return True


def _validate_site_marvis_feedback_type(feedback_type: str) -> bool:  # Validate feedback type against allowlist
    """Return True when feedback type is in the supported allowlist."""
    value = str(feedback_type or "").strip().lower()
    if value not in SITE_MARVIS_ALLOWED_FEEDBACK_TYPES:
        print(f"! Invalid feedback type. Allowed values: {', '.join(sorted(SITE_MARVIS_ALLOWED_FEEDBACK_TYPES))}")
        return False
    return True


def _validate_site_marvis_feedback_comment(comment: str, max_length: int = 500) -> bool:  # Validate bounded comments
    """Return True when feedback comment length is within configured bounds."""
    value = str(comment or "")
    if len(value) > max_length:
        print(f"! Comment is too long ({len(value)} chars). Maximum allowed is {max_length}.")
        return False
    return True


def _validate_site_marvis_feedback_value(feedback_type: str, feedback_value: str) -> bool:  # Validate feedback value semantics
    """Return True when feedback value is populated for supported feedback types."""
    value = str(feedback_value or "").strip()
    if not value:
        print("! Feedback value is required.")
        return False
    if feedback_type in SITE_MARVIS_ALLOWED_FEEDBACK_TYPES:
        return True
    print("! Unsupported feedback type/value combination.")
    return False


def _prompt_site_marvis_scope_input(prompt_map: dict, context: str = "site_marvis") -> Optional[dict]:  # Collect scope/filters for site marvis operations
    """Prompt for org/site scope, optional window values, and optional filter values."""
    org_id = get_cached_or_prompted_org_id()
    site_id_input = safe_input("Enter site ID: ", context=f"{context}_site_id", allow_empty=False)
    site_id = str(site_id_input or "").strip()
    if not site_id:
        print("! Site ID is required. Aborting.")
        return None
    duration_input = safe_input("Duration (e.g. 1d, 2h) [optional]: ", context=f"{context}_duration")
    duration = str(duration_input or "").strip()
    if not _validate_duration_input(duration):
        return None
    start_time = str(safe_input("Start (epoch/relative, optional): ", context=f"{context}_start") or "").strip()
    end_time = str(safe_input("End (epoch/relative, optional): ", context=f"{context}_end") or "").strip()
    if not _validate_site_marvis_time_window(start_time, end_time):
        return None
    filters = _prompt_optional_filters(prompt_map)
    return {
        "org_id": org_id,
        "site_id": site_id,
        "duration": duration,
        "start": start_time,
        "end": end_time,
        "filters": filters,
    }


def _normalize_site_marvis_action_records(raw_data, org_id: str, site_id: str, record_key: str = "id", page_number: int = 1) -> list:  # Normalize site marvis API payloads to deterministic rows
    """Normalize raw site marvis payloads into export-safe rows with scope keys."""
    timestamp = datetime.now(timezone.utc).isoformat()
    rows = raw_data if isinstance(raw_data, list) else [raw_data]
    normalized_rows = []
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            row = {"value": row}
        normalized_row = dict(row)
        normalized_row.setdefault("org_id", org_id)
        normalized_row.setdefault("site_id", site_id)
        normalized_row.setdefault("timestamp", timestamp)
        normalized_row.setdefault(
            "action_id", str(normalized_row.get(record_key) or normalized_row.get("id") or f"row-{index}")
        )
        normalized_row.setdefault("record_id", normalized_row["action_id"])
        normalized_row.setdefault("page_number", page_number)
        normalized_rows.append(normalized_row)
    return normalized_rows


def _build_site_marvis_filters_hash(scope_filters: dict, duration: str, start_time: str, end_time: str) -> str:  # Build deterministic scope token for count snapshots
    """Build deterministic string token describing the filter/window scope."""
    return json.dumps(
        {
            "duration": duration or "",
            "end": end_time or "",
            "filters": scope_filters or {},
            "start": start_time or "",
        },
        sort_keys=True,
    )


def _handle_site_marvis_config_pagination(search_fn, site_id: str, base_params: dict, page_limit: int = 100) -> list:  # Traverse paginated site marvis search responses
    """Collect paginated rows for site marvis config actions with restart guidance on token issues."""
    query_params = dict(base_params)
    query_params["limit"] = page_limit
    supports_search_after = "search_after" in inspect.signature(search_fn).parameters
    token_input = safe_input(
        "Optional search_after token (press Enter to start from first page): ",
        context="site_marvis_search_after",
    )
    token = str(token_input or "").strip()
    if token and not supports_search_after:
        print("! This SDK endpoint does not accept search_after directly. Continuing from first page.")
    if token and supports_search_after:
        query_params["search_after"] = token
    collected_rows = []
    page_number = 1
    while page_number <= 200:
        try:
            response = search_fn(apisession, site_id, **query_params)
        except Exception as page_error:
            error_text = str(page_error)
            if supports_search_after and ("search_after" in error_text.lower() or "token" in error_text.lower()):
                print(f"! Invalid or expired continuation token: {page_error}")
                restart_input = safe_input("Restart from first page? (y/N): ", default_value="n", context="site_marvis_restart")
                restart = str(restart_input or "").strip().lower()
                if restart in {"y", "yes"}:
                    query_params.pop("search_after", None)
                    collected_rows = []
                    page_number = 1
                    continue
            print(f"! Search page retrieval failed after {page_number - 1} page(s): {page_error}")
            break
        payload = getattr(response, "data", []) or []
        page_rows = payload.get("results", []) if isinstance(payload, dict) and "results" in payload else payload
        if not isinstance(page_rows, list):
            page_rows = [page_rows]
        collected_rows.extend(page_rows)
        if not isinstance(payload, dict):
            break
        next_token = str(payload.get("search_after", "") or "").strip()
        if not next_token:
            break
        if not supports_search_after:
            print(
                "! Additional continuation token returned but endpoint signature has no search_after support; stopping at first page."
            )
            break
        query_params["search_after"] = next_token
        page_number += 1
    logging.info("SITE_MARVIS_CONFIG: pagination complete rows=%d pages=%d", len(collected_rows), page_number)
    return collected_rows


def _export_site_marvis_dataset(rows: list, filename: str, api_function_name: str) -> bool:  # Shared export helper for site marvis handlers
    """Export normalized site marvis rows and return True on success."""
    flattened_rows = escape_multiline_strings_for_csv(flatten_nested_fields_in_list(rows))
    try:
        DataExporter.save_data_to_output(flattened_rows, filename, api_function_name=api_function_name)
    except Exception as export_error:
        print(f"[ERROR] Failed to write {filename}: {export_error}")
        logging.error("SITE_MARVIS_CONFIG: Export failed for %s: %s", api_function_name, export_error)
        return False
    return True


def _count_site_marvis_config_actions():  # Menu 216
    """Count site Marvis config actions for selected scope and export deterministic count rows."""
    logging.info("SITE_MARVIS_CONFIG: Starting Menu 216 - Count Site Marvis Config Actions")
    scope = _prompt_site_marvis_scope_input(
        {
            "distinct": "Distinct group key (mac/type/src/admin_id/op/port_id/reason/vlan_ids)",
            "mac": "Filter MAC",
            "type": "Filter type",
            "src": "Filter source",
            "admin_id": "Filter admin ID",
            "op": "Filter operation",
            "port_id": "Filter port ID",
            "vlan_ids": "Filter VLAN ID",
            "reason": "Filter reason",
        },
        context="site_marvis_count",
    )
    if scope is None:
        return
    api_params = dict(scope["filters"])
    api_params["duration"] = scope["duration"] or None
    api_params["end"] = scope["end"] or None
    api_params["limit"] = 1000
    api_params["start"] = scope["start"] or None
    try:
        response = mistapi.api.v1.sites.marvis_configs.countSiteMarvisConfigActions(
            apisession, scope["site_id"], **api_params
        )
    except Exception as count_error:
        print(f"[ERROR] Site Marvis config action count failed: {count_error}")
        logging.error("SITE_MARVIS_CONFIG: countSiteMarvisConfigActions failed: %s", count_error)
        return
    payload = getattr(response, "data", {}) or {}
    normalized_rows = _normalize_site_marvis_action_records(
        payload,
        scope["org_id"],
        scope["site_id"],
        record_key="distinct",
        page_number=1,
    )
    filters_hash = _build_site_marvis_filters_hash(scope["filters"], scope["duration"], scope["start"], scope["end"])
    for normalized_row in normalized_rows:
        normalized_row["filters_hash"] = filters_hash
        normalized_row["group_key"] = str(
            scope["filters"].get("distinct") or normalized_row.get("distinct") or "total"
        )
        normalized_row["window_end"] = scope["end"] or ""
        normalized_row["window_start"] = scope["start"] or ""
    if not _export_site_marvis_dataset(
        normalized_rows,
        "SiteMarvisConfigActionsCount.csv",
        "countSiteMarvisConfigActions",
    ):
        return
    print(f"! Site config action count export complete. rows={len(normalized_rows)} site_id={scope['site_id']}")


